import unittest
from your_application import Order, Product, InsufficientStockError

class TestInsufficientStock(unittest.TestCase):
    def setUp(self):
        self.product = Product(name="Test Product", stock=5)  # Set initial stock

    def test_insufficient_stock_during_order_placement(self):
        order_quantity = 10  # Order more than available stock
        with self.assertRaises(InsufficientStockError):
            Order.place_order(product=self.product, quantity=order_quantity)  # Attempt to place order

if __name__ == '__main__':
    unittest.main()

